P = [('GANK','#2fa59a',1,'Cloister',''),('Ysolde','#e08a32',1,'Cloister',''),('Konstantin','#9b5fd0',1,'Larder',''),('Mira','#d9573f',0,'',''),('Bartholomew','#4f8fd9',1,'Chapel','bot'),('Odile','#e3c04a',1,'Gatehouse','')]
def plan(S, k=92, small=False):
    h = ''
    for i,(n,x,y,w,hh) in enumerate(S['rooms']):
        pips = ''.join(f'<i style="background:{c}"></i>' for (_,c,a,rm,_) in P if a and S['rooms'][[r[0] for r in SET['mon']['rooms']].index(rm)][0]==n) if not small else ''
        here = (not small and i==2)
        h += f'<div class="room{" here" if here else ""}" style="left:{x*k}px;top:{y*k}px;width:{w*k-6}px;height:{hh*k-6}px;background:{S["floor"]};border-color:{S["acc"] if here else S["wall"]}"><b style="color:{S["ink"]};font-size:{9 if small else 14}px">{n}</b><div class="pips">{pips}</div>{"" if small else f"<span class=log>{[2,0,3,1,2,0,0,1][i]} visits today</span>"}</div>'
    return f'<div class="plan" style="width:{5*k}px;height:{5*k}px">{h}</div>'
S = SET['mon']
gauge = lambda n,v: f'<div class="g"><span>{n}</span><div>{"".join(f"<i class={ "on" if j<v else "off"}{" low" if v<=1 else ""}></i>" for j in range(5))}</div></div>'
