{''.join(f'<div class="pl{"" if a else " dead"}"><i style="background:{c}"></i><div><b style="color:{c}">{n}</b>{" <span class=dim style=font-size:11px>bot</span>" if t else ""}<div class="dim" style="font-size:11px">{("in the "+rm) if a else "executed day 2 · ghost, 1 vote left"}</div></div><span class="v dim">{"you" if n=="GANK" else "whisper"}</span></div>' for (n,c,a,rm,t) in P)}
